function buildCloud(camName) {{
    const data = CAM_DATA[camName];
    if (!data || data.length === 0) return null;

    const positions = new Float32Array(data.length * 3);
    const rgbColors = new Float32Array(data.length * 3);
    const camColor = new THREE.Color(CAM_COLORS[camName] || '#ffffff');

    for (let i = 0; i < data.length; i++) {{
        positions[i*3]   = data[i][0];
        positions[i*3+1] = data[i][1];
        positions[i*3+2] = data[i][2];
        rgbColors[i*3]   = data[i][3] / 255;
        rgbColors[i*3+1] = data[i][4] / 255;
        rgbColors[i*3+2] = data[i][5] / 255;
    }}

    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geom.setAttribute('color', new THREE.BufferAttribute(rgbColors, 3));
    const camColors = new Float32Array(data.length * 3);
    for (let i = 0; i < data.length; i++) {{
        camColors[i*3]   = camColor.r;
        camColors[i*3+1] = camColor.g;
        camColors[i*3+2] = camColor.b;
    }}
    geom.userData = {{ rgbColors: rgbColors, camColors: camColors }};

    const mat = new THREE.PointsMaterial({{
        size: 2, sizeAttenuation: false, vertexColors: true
    }});
    return new THREE.Points(geom, mat);
}}

